def list_locations(api_key, query=None, city_name_en=None, city_name_zh_cn=None, country_code=None, admin1=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0318000" if __import__("os").path.isdir("./environment_mix/0318000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(6).hex()}"

    def _norm(s):
        return " ".join((s or "").strip().lower().split())

    def _hash_candidates(k):
        k = k if isinstance(k, str) else ""
        b = k.encode("utf-8")
        cands = set()
        cands.add(hashlib.sha256(b).hexdigest())
        cands.add(hashlib.sha1(b).hexdigest())
        cands.add(hashlib.md5(b).hexdigest())
        cands.add(base64.b64encode(hashlib.sha256(b).digest()).decode("ascii"))
        cands.add(base64.b64encode(hashlib.sha1(b).digest()).decode("ascii"))
        cands.add(base64.b64encode(hashlib.md5(b).digest()).decode("ascii"))
        return cands

    t0 = time.time()
    now = _now()

    # validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    if city_name_en is not None and not isinstance(city_name_en, str):
        return _err("VALIDATION_ERROR", "city_name_en must be a string")
    if city_name_zh_cn is not None and not isinstance(city_name_zh_cn, str):
        return _err("VALIDATION_ERROR", "city_name_zh_cn must be a string")
    if country_code is not None:
        if not isinstance(country_code, str):
            return _err("VALIDATION_ERROR", "country_code must be a string")
        cc = country_code.strip()
        if len(cc) != 2:
            return _err("VALIDATION_ERROR", "country_code must be 2 characters")
    if admin1 is not None and not isinstance(admin1, str):
        return _err("VALIDATION_ERROR", "admin1 must be a string")
    if status is not None and status not in ("active", "deprecated"):
        return _err("VALIDATION_ERROR", "status must be one of: active, deprecated")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    api_keys = _load("api_keys.json")
    locations = _load("locations.json")
    reqs = _load("weather_requests.json")
    counters = _load("usage_counters.json")

    # authenticate
    key_row = None
    api_key_in = api_key.strip()
    cands = _hash_candidates(api_key_in)
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key_in:
            key_row = r
            break
        kh = r.get("key_hash")
        if isinstance(kh, str) and kh in cands:
            key_row = r
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "api_key is missing or invalid")
    api_key_id = key_row.get("id")

    # enforce key status (counts as failed request per business rules for non-active keys)
    def _bucket_start(dt, window_type):
        if window_type == "minute":
            return dt.replace(second=0, microsecond=0)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _get_counter(window_type):
        ws = _bucket_start(now, window_type)
        ws_iso = _dt_iso(ws)
        for row in counters:
            if row.get("api_key_id") == api_key_id and row.get("window_type") == window_type and row.get("window_start") == ws_iso:
                return row
        row = {
            "id": _new_id("uc"),
            "api_key_id": api_key_id,
            "window_start": ws_iso,
            "window_type": window_type,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "rate_limited_count": 0,
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }
        counters.append(row)
        return row

    minute_ctr = _get_counter("minute")
    day_ctr = _get_counter("day")

    if key_row.get("status") != "active":
        # record as failed weather_requests row for tool invocation semantics? Tool is list_locations, but schema tool_name enum doesn't include it.
        # Therefore, only usage counters can be updated; return UNAUTHORIZED.
        minute_ctr["request_count"] += 1
        day_ctr["request_count"] += 1
        minute_ctr["error_count"] += 1
        day_ctr["error_count"] += 1
        minute_ctr["updated_at"] = _dt_iso(now)
        day_ctr["updated_at"] = _dt_iso(now)
        _save("usage_counters.json", counters)
        return _err("UNAUTHORIZED", "API key is not active")

    # rate limit / quota (applies to tool invocation even though not in weather_requests enum)
    rpm_limit = key_row.get("requests_per_minute_limit")
    rpd_limit = key_row.get("requests_per_day_limit")
    if not isinstance(rpm_limit, int) or rpm_limit < 1 or not isinstance(rpd_limit, int) or rpd_limit < 1:
        return _err("VALIDATION_ERROR", "API key limits are misconfigured")

    would_minute = minute_ctr["request_count"] + 1
    would_day = day_ctr["request_count"] + 1
    if would_minute > rpm_limit or would_day > rpd_limit:
        minute_ctr["request_count"] += 1
        day_ctr["request_count"] += 1
        minute_ctr["rate_limited_count"] += 1
        day_ctr["rate_limited_count"] += 1
        minute_ctr["updated_at"] = _dt_iso(now)
        day_ctr["updated_at"] = _dt_iso(now)
        _save("usage_counters.json", counters)
        if would_minute > rpm_limit:
            return _err("RATE_LIMIT", "requests_per_minute_limit exceeded")
        return _err("QUOTA_EXCEEDED", "requests_per_day_limit exceeded")

    # apply filtering
    qn = _norm(query) if query else None
    en_f = _norm(city_name_en) if city_name_en else None
    zh_f = _norm(city_name_zh_cn) if city_name_zh_cn else None
    cc_f = country_code.strip().upper() if isinstance(country_code, str) and country_code.strip() else None
    admin_f = _norm(admin1) if admin1 else None

    def _match(loc):
        if not isinstance(loc, dict):
            return False
        if status is not None and loc.get("status") != status:
            return False
        if cc_f is not None:
            if (loc.get("country_code") or "").upper() != cc_f:
                return False
        if admin_f is not None:
            if _norm(loc.get("admin1") or "") != admin_f:
                return False
        if en_f is not None:
            en = _norm(loc.get("city_name_en") or "")
            if not (en == en_f or en.startswith(en_f)):
                return False
        if zh_f is not None:
            zh = _norm(loc.get("city_name_zh_cn") or "")
            if not (zh == zh_f or zh.startswith(zh_f)):
                return False
        if qn is not None:
            hay = " ".join(
                [
                    _norm(loc.get("city_name_en") or ""),
                    _norm(loc.get("city_name_zh_cn") or ""),
                    _norm(loc.get("admin1") or ""),
                    _norm((loc.get("country_code") or "").upper()),
                ]
            )
            if qn not in hay:
                return False
        return True

    matched = [l for l in locations if _match(l)]
    # stable sort: active first, then city_name_en, then id
    def _sort_key(l):
        st = l.get("status")
        return (0 if st == "active" else 1, (l.get("city_name_en") or "").lower(), l.get("id") or "")
    matched.sort(key=_sort_key)

    # pagination via cursor as integer offset (opaque)
    offset = 0
    if cursor:
        try:
            offset = int(cursor)
            if offset < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    page = matched[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(matched)
    next_cursor = str(next_offset) if has_more else None

    # update usage counters as success
    minute_ctr["request_count"] += 1
    day_ctr["request_count"] += 1
    minute_ctr["success_count"] += 1
    day_ctr["success_count"] += 1
    minute_ctr["updated_at"] = _dt_iso(now)
    day_ctr["updated_at"] = _dt_iso(now)
    _save("usage_counters.json", counters)

    return {
        "data": page,
        "meta": {
            "total": len(matched),
            "limit": limit,
            "cursor": str(offset),
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
        },
    }

