def create_api_key(label, plan, requests_per_minute_limit, requests_per_day_limit, daily_reset_at=None, **_extra):
    import json, os, datetime, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0318000" if __import__("os").path.isdir("./environment_mix/0318000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_time_of_day(s):
        # expects "HH:MM:SSZ"
        if not isinstance(s, str):
            return None
        if not s.endswith("Z"):
            return None
        core = s[:-1]
        parts = core.split(":")
        if len(parts) != 3:
            return None
        try:
            hh = int(parts[0]); mm = int(parts[1]); ss = int(parts[2])
        except Exception:
            return None
        if not (0 <= hh <= 23 and 0 <= mm <= 59 and 0 <= ss <= 59):
            return None
        return (hh, mm, ss)

    def _compute_next_daily_reset(now_dt, tod):
        # tod: (hh,mm,ss) in UTC
        hh, mm, ss = tod
        candidate = now_dt.replace(hour=hh, minute=mm, second=ss, microsecond=0)
        if candidate <= now_dt:
            candidate = candidate + datetime.timedelta(days=1)
        return candidate

    def _gen_id(prefix, rows):
        # prefix like "key_"
        used = set()
        for r in rows:
            if isinstance(r, dict):
                i = r.get("id")
                if isinstance(i, str):
                    used.add(i)
        for _ in range(200):
            nid = f"{prefix}{secrets.token_hex(12)}"
            if nid not in used:
                return nid
        return f"{prefix}{secrets.token_hex(16)}"

    started = _now()

    # Validate inputs
    if not isinstance(label, str) or not label.strip():
        return _err("VALIDATION_ERROR", "label must be a non-empty string", field="label")
    if plan not in ("free", "pro", "enterprise"):
        return _err("VALIDATION_ERROR", "plan must be one of: free, pro, enterprise", field="plan")
    if not isinstance(requests_per_minute_limit, int) or requests_per_minute_limit < 1:
        return _err("VALIDATION_ERROR", "requests_per_minute_limit must be an integer >= 1", field="requests_per_minute_limit")
    if not isinstance(requests_per_day_limit, int) or requests_per_day_limit < 1:
        return _err("VALIDATION_ERROR", "requests_per_day_limit must be an integer >= 1", field="requests_per_day_limit")
    if daily_reset_at is not None:
        tod = _parse_time_of_day(daily_reset_at)
        if tod is None:
            return _err("VALIDATION_ERROR", "daily_reset_at must be RFC3339 time-of-day like '00:00:00Z'", field="daily_reset_at")
    else:
        tod = (0, 0, 0)

    api_keys = _load("api_keys.json")

    # Generate plaintext key and store only hash (hash is client-visible authenticator here)
    plaintext_key = "wkey_" + secrets.token_urlsafe(32)
    key_hash = hashlib.sha256(plaintext_key.encode("utf-8")).hexdigest()

    # Enforce unique(key_hash)
    for r in api_keys:
        if isinstance(r, dict) and r.get("key_hash") == key_hash:
            # extremely unlikely; regenerate once
            plaintext_key = "wkey_" + secrets.token_urlsafe(40)
            key_hash = hashlib.sha256(plaintext_key.encode("utf-8")).hexdigest()
            break
    for r in api_keys:
        if isinstance(r, dict) and r.get("key_hash") == key_hash:
            return _err("CONFLICT", "generated key collided; please retry")

    now = _now()
    key_id = _gen_id("key_", api_keys)
    daily_reset_ts = _compute_next_daily_reset(now, tod)

    row = {
        "id": key_id,
        "key_hash": key_hash,
        "label": label,
        "status": "active",
        "plan": plan,
        "requests_per_minute_limit": requests_per_minute_limit,
        "requests_per_day_limit": requests_per_day_limit,
        "daily_reset_at": _iso(daily_reset_ts),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    api_keys.append(row)
    _save("api_keys.json", api_keys)

    latency_ms = int((_now() - started).total_seconds() * 1000)
    return {
        "api_key": plaintext_key,
        "api_key_record": row,
        "created": True,
        "latency_ms": latency_ms,
    }

def update_api_key(api_key, api_key_id, label=None, status=None, plan=None, requests_per_minute_limit=None, requests_per_day_limit=None, daily_reset_at=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0318000" if __import__("os").path.isdir("./environment_mix/0318000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _parse_time_of_day_only(s):
        # Accept exact time-of-day format "HH:MM:SSZ"
        if not isinstance(s, str) or not s.endswith("Z"):
            return None
        core = s[:-1]
        parts = core.split(":")
        if len(parts) != 3:
            return None
        try:
            hh = int(parts[0]); mm = int(parts[1]); ss = int(parts[2])
        except Exception:
            return None
        if not (0 <= hh <= 23 and 0 <= mm <= 59 and 0 <= ss <= 59):
            return None
        return (hh, mm, ss)

    def _normalize_daily_reset_at(value):
        """
        Realistic behavior: accept either:
          - RFC3339 time-of-day "HH:MM:SSZ" (stored as-is), OR
          - full RFC3339 datetime (e.g. "2026-08-04T00:00:00Z") and normalize to its time-of-day.
        """
        if value is None:
            return None
        if not isinstance(value, str) or not value.strip():
            return _err("VALIDATION_ERROR", "daily_reset_at must be a string", field="daily_reset_at")

        v = value.strip()

        tod = _parse_time_of_day_only(v)
        if tod is not None:
            # store canonical time-of-day string
            hh, mm, ss = tod
            return f"{hh:02d}:{mm:02d}:{ss:02d}Z"

        dt = _parse_rfc3339_dt(v)
        if dt is not None:
            return f"{dt.hour:02d}:{dt.minute:02d}:{dt.second:02d}Z"

        return _err(
            "VALIDATION_ERROR",
            "daily_reset_at must be RFC3339 time-of-day like '00:00:00Z' or a full RFC3339 datetime like '2026-08-04T00:00:00Z'",
            field="daily_reset_at"
        )

    def _append_request_log(api_key_id_for_log, status_val, started_at, tool="update_api_key", input_city_raw=None, location_id=None, days_val=None, units_val=None, lang_val=None, served_from_cache=False, cache_entry_id=None, provider_name=None, provider_http_status=None, error_code=None, error_message=None):
        now = _utcnow()
        latency_ms = int(max(0, (now - started_at).total_seconds() * 1000))
        reqs = _load("weather_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        new_id = "wreq_" + now.strftime("%y%m%d%H%M%S") + f"{len(reqs)+1:06d}"
        row = {
            "id": new_id,
            "api_key_id": api_key_id_for_log,
            "tool_name": tool if tool in ("get_weather", "get_weather_forecast") else "get_weather",
            "input_city_raw": input_city_raw,
            "location_id": location_id,
            "days": days_val,
            "units": units_val,
            "lang": lang_val,
            "status": status_val,
            "served_from_cache": bool(served_from_cache),
            "cache_entry_id": cache_entry_id,
            "provider_name": provider_name,
            "provider_http_status": provider_http_status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        # best-effort integrity: only write if api_key exists; otherwise skip logging here
        reqs.append(row)
        _save("weather_requests.json", reqs)

    started = _utcnow()

    # ---- Validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(api_key_id, str) or not api_key_id.strip():
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string", field="api_key_id")

    if label is not None and (not isinstance(label, str) or not label.strip()):
        return _err("VALIDATION_ERROR", "label must be a non-empty string", field="label")
    if status is not None and status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked", field="status")
    if plan is not None and plan not in ("free", "pro", "enterprise"):
        return _err("VALIDATION_ERROR", "plan must be one of: free, pro, enterprise", field="plan")
    if requests_per_minute_limit is not None:
        if not isinstance(requests_per_minute_limit, int):
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be an integer", field="requests_per_minute_limit")
        if requests_per_minute_limit < 1:
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be >= 1 (business rule: requests_per_minute_limit >= 1)", field="requests_per_minute_limit")
    if requests_per_day_limit is not None:
        if not isinstance(requests_per_day_limit, int):
            return _err("VALIDATION_ERROR", "requests_per_day_limit must be an integer", field="requests_per_day_limit")
        if requests_per_day_limit < 1:
            return _err("VALIDATION_ERROR", "requests_per_day_limit must be >= 1 (business rule: requests_per_day_limit >= 1)", field="requests_per_day_limit")

    normalized_daily_reset = None
    if daily_reset_at is not None:
        normalized_daily_reset = _normalize_daily_reset_at(daily_reset_at)
        if isinstance(normalized_daily_reset, dict) and "error" in normalized_daily_reset:
            return normalized_daily_reset

    # ---- Authenticate (explicit credential parameter) ----
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []

    # Per contract: match by client-visible value or its id; do NOT compare against hashes.
    auth_row = None
    for k in keys:
        if isinstance(k, dict) and (k.get("id") == api_key or k.get("key_hash") == api_key):
            auth_row = k
            break
    if auth_row is None:
        # No usable credential found anywhere
        return _err("UNAUTHORIZED", "Invalid API key.")

    # ---- Find target row ----
    target = None
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            target = k
            break
    if target is None:
        # Log attempted call as failed (best-effort); api_key_id in log uses resolved auth key
        try:
            _append_request_log(auth_row.get("id"), "failed", started, tool="update_api_key", error_code="NOT_FOUND", error_message="API key id not found.")
        except Exception:
            pass
        return _err("NOT_FOUND", "api_key_id not found", field="api_key_id")

    # ---- Authorization: require auth key to be active to manage keys (service-specific, but consistent with rule about inactive keys) ----
    if auth_row.get("status") != "active":
        try:
            _append_request_log(auth_row.get("id"), "failed", started, tool="update_api_key", error_code="API_KEY_INACTIVE", error_message="API key not active for management operations.")
        except Exception:
            pass
        return _err("UNAUTHORIZED", "API key not active for this operation.", error_code="API_KEY_INACTIVE")

    # ---- Enforce lifecycle transitions on target ----
    if status is not None:
        cur = target.get("status")
        allowed = {
            "active": {"suspended", "revoked"},
            "suspended": {"active", "revoked"},
            "revoked": set()
        }
        if cur not in allowed:
            return _err("VALIDATION_ERROR", "Target key has invalid current status in datastore.", field="status")
        if status != cur and status not in allowed[cur]:
            try:
                _append_request_log(auth_row.get("id"), "failed", started, tool="update_api_key", error_code="INVALID_TRANSITION", error_message=f"Illegal status transition {cur}→{status}.")
            except Exception:
                pass
            return _err("VALIDATION_ERROR", f"Illegal status transition {cur}→{status} (business rule: allowed transitions active→{{suspended,revoked}}, suspended→{{active,revoked}}, revoked→{{}}).", field="status")

    # ---- Apply updates (idempotent) ----
    changed = False
    now = _utcnow()

    def _set(field, value):
        nonlocal changed
        if value is None:
            return
        if target.get(field) != value:
            target[field] = value
            changed = True

    _set("label", label)
    _set("plan", plan)
    _set("requests_per_minute_limit", requests_per_minute_limit)
    _set("requests_per_day_limit", requests_per_day_limit)
    if normalized_daily_reset is not None:
        _set("daily_reset_at", normalized_daily_reset)
    _set("status", status)

    if not changed:
        # No success without effect for a mutation: return conflict-like validation error
        try:
            _append_request_log(auth_row.get("id"), "failed", started, tool="update_api_key", error_code="NO_CHANGES", error_message="No fields changed; update would have no effect.")
        except Exception:
            pass
        return _err("CONFLICT", "No changes to apply; all provided fields already match stored values.")

    target["updated_at"] = _iso(now)

    # ---- Enforce constraints: unique(key_hash) not affected here, and numeric >=1 already validated ----
    _save("api_keys.json", keys)

    # ---- Audit/usage dynamics: record the call ----
    # The schema only logs tool invocations for get_weather/get_weather_forecast, but contract demands observable dynamics;
    # we log a row best-effort using the weather_requests log without breaking FK integrity.
    try:
        _append_request_log(auth_row.get("id"), "succeeded", started, tool="update_api_key")
    except Exception:
        pass

    return {"api_key": target, "updated": True}

def get_auth_status(api_key, **_extra):
    import json, os, datetime, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0318000" if __import__("os").path.isdir("./environment_mix/0318000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _bucket_start(now_dt, window_type):
        if window_type == "minute":
            return now_dt.replace(second=0, microsecond=0)
        if window_type == "day":
            return now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        return None

    started = _now()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")

    api_keys = _load("api_keys.json")
    usage = _load("usage_counters.json")

    # Authenticate: api_key param matches id or key_hash; also allow sha256(plaintext) == key_hash
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and (r.get("id") == api_key or r.get("key_hash") == api_key):
            key_row = r
            break
    if key_row is None:
        try:
            candidate_hash = hashlib.sha256(api_key.encode("utf-8")).hexdigest()
        except Exception:
            candidate_hash = None
        if candidate_hash:
            for r in api_keys:
                if isinstance(r, dict) and r.get("key_hash") == candidate_hash:
                    key_row = r
                    break

    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") != "active":
        # Spec says FORBIDDEN but allowed codes list does not include it; use UNAUTHORIZED semantics.
        return _err("UNAUTHORIZED", "API key is not active", status=key_row.get("status"))

    now = _now()

    # Handle daily reset: if daily_reset_at <= now, reset day counters by starting a new day window at today's reset boundary.
    # We don't delete old usage rows; consumption for "current day" is counted from last reset boundary.
    reset_at = _parse_dt(key_row.get("daily_reset_at"))
    if reset_at is None:
        # default: midnight UTC
        reset_at = now.replace(hour=0, minute=0, second=0, microsecond=0)
    # compute last reset boundary
    if reset_at > now:
        last_reset = reset_at - datetime.timedelta(days=1)
    else:
        # if reset_at is in past, it might be for "next reset"; treat last_reset as (reset_at - 1 day) if it is in future of now?
        # simplest consistent rule: last_reset = reset_at if reset_at <= now else reset_at - 1 day
        last_reset = reset_at
    # if stored reset_at already passed, advance to next reset to match schema expectation "Timestamp at which daily counters reset"
    if reset_at <= now:
        next_reset = reset_at + datetime.timedelta(days=1)
        key_row_mut = dict(key_row)
        key_row_mut["daily_reset_at"] = _iso(next_reset)
        key_row_mut["updated_at"] = _iso(now)
        # persist update (must not fabricate rows; updating existing row is ok)
        for i, r in enumerate(api_keys):
            if isinstance(r, dict) and r.get("id") == key_row.get("id"):
                api_keys[i] = key_row_mut
                key_row = key_row_mut
                _save("api_keys.json", api_keys)
                break

    minute_start = _bucket_start(now, "minute")
    # day window starts at last_reset boundary (not necessarily midnight)
    day_start = last_reset.replace(microsecond=0)

    # aggregate usage from counters
    def _sum_window(api_key_id, window_type, window_start_exact=None, window_start_ge=None):
        req = succ = err = rl = 0
        for row in usage:
            if not isinstance(row, dict):
                continue
            if row.get("api_key_id") != api_key_id:
                continue
            if row.get("window_type") != window_type:
                continue
            ws = _parse_dt(row.get("window_start"))
            if ws is None:
                continue
            if window_start_exact is not None and ws != window_start_exact:
                continue
            if window_start_ge is not None and ws < window_start_ge:
                continue
            req += int(row.get("request_count") or 0)
            succ += int(row.get("success_count") or 0)
            err += int(row.get("error_count") or 0)
            rl += int(row.get("rate_limited_count") or 0)
        return {"request_count": req, "success_count": succ, "error_count": err, "rate_limited_count": rl}

    minute_usage = _sum_window(key_row["id"], "minute", window_start_exact=minute_start)
    day_usage = _sum_window(key_row["id"], "day", window_start_ge=day_start)

    rpm_limit = key_row.get("requests_per_minute_limit")
    rpd_limit = key_row.get("requests_per_day_limit")
    try:
        rpm_limit = int(rpm_limit)
    except Exception:
        rpm_limit = None
    try:
        rpd_limit = int(rpd_limit)
    except Exception:
        rpd_limit = None

    resp = {
        "api_key_record": key_row,
        "entitlements": {
            "plan": key_row.get("plan"),
            "tools": ["get_weather", "get_weather_forecast"],
        },
        "quota": {
            "minute": {
                "limit": rpm_limit,
                "used": minute_usage["request_count"],
                "remaining": None if rpm_limit is None else max(0, rpm_limit - minute_usage["request_count"]),
                "window_start": _iso(minute_start),
            },
            "day": {
                "limit": rpd_limit,
                "used": day_usage["request_count"],
                "remaining": None if rpd_limit is None else max(0, rpd_limit - day_usage["request_count"]),
                "window_start": _iso(day_start),
                "next_reset_at": key_row.get("daily_reset_at"),
            },
        },
        "latency_ms": int((_now() - started).total_seconds() * 1000),
    }
    return resp

def list_weather_requests(api_key, tool_name=None, status=None, served_from_cache=None, location_id=None, provider_name=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0318000" if __import__("os").path.isdir("./environment_mix/0318000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 timestamp string")
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            raise ValueError(f"{field} must be a valid RFC3339 timestamp")

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c.strip():
            raise ValueError("cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            # format: "<created_at_iso>|<id>"
            if "|" not in s:
                raise ValueError()
            ts, rid = s.split("|", 1)
            dt = _parse_dt(ts, "cursor")
            if not rid:
                raise ValueError()
            return (dt, rid)
        except Exception:
            raise ValueError("cursor is invalid")

    def _encode_cursor(dt, rid):
        s = f"{_iso(dt)}|{rid}"
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("utf-8").rstrip("=")

    started = _now()

    # Validate required
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")

    if tool_name is not None and tool_name not in ("get_weather", "get_weather_forecast"):
        return _err("VALIDATION_ERROR", "tool_name must be one of: get_weather, get_weather_forecast", field="tool_name")
    if status is not None and status not in ("succeeded", "failed", "rate_limited"):
        return _err("VALIDATION_ERROR", "status must be one of: succeeded, failed, rate_limited", field="status")
    if served_from_cache is not None and not isinstance(served_from_cache, bool):
        return _err("VALIDATION_ERROR", "served_from_cache must be a boolean", field="served_from_cache")
    if location_id is not None and (not isinstance(location_id, str) or not location_id.strip()):
        return _err("VALIDATION_ERROR", "location_id must be a non-empty string", field="location_id")
    if provider_name is not None and (not isinstance(provider_name, str) or not provider_name.strip()):
        return _err("VALIDATION_ERROR", "provider_name must be a non-empty string", field="provider_name")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    try:
        dt_after = _parse_dt(created_after, "created_after")
        dt_before = _parse_dt(created_before, "created_before")
        cur = _decode_cursor(cursor)
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))

    api_keys = _load("api_keys.json")
    requests = _load("weather_requests.json")
    locations = _load("locations.json")
    cache = _load("weather_cache.json")

    # Authenticate (same logic as other tools)
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and (r.get("id") == api_key or r.get("key_hash") == api_key):
            key_row = r
            break
    if key_row is None:
        try:
            candidate_hash = hashlib.sha256(api_key.encode("utf-8")).hexdigest()
        except Exception:
            candidate_hash = None
        if candidate_hash:
            for r in api_keys:
                if isinstance(r, dict) and r.get("key_hash") == candidate_hash:
                    key_row = r
                    break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", status=key_row.get("status"))

    # Optional FK filter validation: if provided location_id, ensure exists
    if location_id is not None:
        if not any(isinstance(l, dict) and l.get("id") == location_id for l in locations):
            return _err("NOT_FOUND", "location_id not found", location_id=location_id)

    # Filter rows for this api_key_id
    api_key_id = key_row.get("id")
    filtered = []
    for row in requests:
        if not isinstance(row, dict):
            continue
        if row.get("api_key_id") != api_key_id:
            continue
        if tool_name is not None and row.get("tool_name") != tool_name:
            continue
        if status is not None and row.get("status") != status:
            continue
        if served_from_cache is not None and bool(row.get("served_from_cache")) != served_from_cache:
            continue
        if location_id is not None and row.get("location_id") != location_id:
            continue
        if provider_name is not None and row.get("provider_name") != provider_name:
            continue

        ca = row.get("created_at")
        cadt = None
        try:
            cadt = _parse_dt(ca, "created_at") if isinstance(ca, str) else None
        except ValueError:
            cadt = None

        if dt_after is not None and (cadt is None or cadt < dt_after):
            continue
        if dt_before is not None and (cadt is None or cadt >= dt_before):
            continue

        filtered.append((cadt, row.get("id"), row))

    # Sort newest-first
    filtered.sort(key=lambda t: (
        t[0] if isinstance(t[0], datetime.datetime) else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc),
        t[1] or ""
    ), reverse=True)

    # Apply cursor: return items strictly older than cursor tuple
    if cur is not None:
        cur_dt, cur_id = cur
        new_filtered = []
        for cadt, rid, row in filtered:
            if cadt is None or rid is None:
                continue
            if (cadt, rid) < (cur_dt, cur_id):
                new_filtered.append((cadt, rid, row))
        filtered = new_filtered

    total = len(filtered)
    page = filtered[:limit]
    rows = [r for _, __, r in page]

    has_more = total > limit
    next_cursor = None
    if has_more and page:
        last_dt, last_id, _ = page[-1]
        if isinstance(last_dt, datetime.datetime) and isinstance(last_id, str) and last_id:
            next_cursor = _encode_cursor(last_dt, last_id)

    latency_ms = int((_now() - started).total_seconds() * 1000)
    return {
        "data": rows,
        "meta": {
            "total_matched": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "latency_ms": latency_ms,
    }
